    20→package quickfix.mina.acceptor;
    21→
    22→import org.apache.mina.core.buffer.IoBuffer;
    23→import org.apache.mina.core.buffer.SimpleBufferAllocator;
    24→import org.apache.mina.core.service.IoAcceptor;
    25→import org.apache.mina.filter.codec.ProtocolCodecFilter;
    26→import quickfix.Acceptor;
    27→import quickfix.Application;
    28→import quickfix.ConfigError;
    29→import quickfix.DefaultSessionFactory;
    30→import quickfix.FieldConvertError;
    31→import quickfix.LogFactory;
    32→import quickfix.MessageFactory;
    33→import quickfix.MessageStoreFactory;
    34→import quickfix.RuntimeError;
    35→import quickfix.ScreenLogFactory;
