    38→import quickfix.SessionID;
    39→import quickfix.SessionSettings;
    40→import quickfix.mina.CompositeIoFilterChainBuilder;
    41→import quickfix.mina.EventHandlingStrategy;
    42→import quickfix.mina.NetworkingOptions;
    43→import quickfix.mina.ProtocolFactory;
    44→import quickfix.mina.SessionConnector;
    45→import quickfix.mina.message.FIXProtocolCodecFactory;
    46→import quickfix.mina.ssl.SSLConfig;
    47→import quickfix.mina.ssl.SSLContextFactory;
    48→import quickfix.mina.ssl.SSLFilter;
    49→import quickfix.mina.ssl.SSLSupport;
    50→
    51→import javax.net.ssl.SSLContext;
    52→import java.io.IOException;
    53→import java.net.SocketAddress;
    54→import java.security.GeneralSecurityException;
    55→import java.util.Collection;
    56→import java.util.Collections;
    57→import java.util.HashMap;
    58→import java.util.Iterator;
    59→import java.util.Map;
    60→import java.util.concurrent.ConcurrentHashMap;
    61→import java.util.concurrent.ConcurrentMap;
    62→
    63→/**
    64→ * Abstract base class for socket acceptors.
    65→ */
    66→public abstract class AbstractSocketAcceptor extends SessionConnector implements Acceptor {
    67→    private final Map<SocketAddress, AcceptorSessionProvider> sessionProviders = new HashMap<>();
    68→    private final SessionFactory sessionFactory;
    69→    private final Map<SocketAddress, AcceptorSocketDescriptor> socketDescriptorForAddress = new HashMap<>();
    70→    private final ConcurrentMap<AcceptorSocketDescriptor, IoAcceptor> ioAcceptors = new ConcurrentHashMap<>();
    71→
    72→    protected AbstractSocketAcceptor(SessionSettings settings, SessionFactory sessionFactory)
    73→            throws ConfigError {
    74→        super(settings, sessionFactory);
    75→        IoBuffer.setAllocator(new SimpleBufferAllocator());
    76→        IoBuffer.setUseDirectBuffer(false);
    77→        this.sessionFactory = sessionFactory;
    78→    }
    79→
    80→    protected AbstractSocketAcceptor(Application application,
    81→            MessageStoreFactory messageStoreFactory, SessionSettings settings,
    82→            MessageFactory messageFactory) throws ConfigError {
    83→        this(application, messageStoreFactory, settings, new ScreenLogFactory(settings),
    84→                messageFactory);
    85→    }
    86→
    87→    protected AbstractSocketAcceptor(Application application,
    88→            MessageStoreFactory messageStoreFactory, SessionSettings settings,
    89→            LogFactory logFactory, MessageFactory messageFactory) throws ConfigError {
    90→        this(settings, new DefaultSessionFactory(application, messageStoreFactory, logFactory,
    91→                messageFactory));
    92→    }
    93→
    94→    // TODO SYNC Does this method really need synchronization?
    95→    protected synchronized void startAcceptingConnections() throws ConfigError {
    96→
    97→        boolean continueInitOnError = isContinueInitOnError();
    98→        createSessions(getSettings(), continueInitOnError);
    99→        startSessionTimer();
   100→
   101→        SocketAddress address = null;
   102→        for (AcceptorSocketDescriptor socketDescriptor : socketDescriptorForAddress.values()) {
   103→            try {
   104→                address = socketDescriptor.getAddress();
   105→                IoAcceptor ioAcceptor = getIoAcceptor(socketDescriptor);
   106→                CompositeIoFilterChainBuilder ioFilterChainBuilder = new CompositeIoFilterChainBuilder(getIoFilterChainBuilder());
   107→
   108→                if (socketDescriptor.isUseSSL()) {
   109→                    installSSL(socketDescriptor, ioFilterChainBuilder);
   110→                }
   111→
   112→                ioFilterChainBuilder.addLast(FIXProtocolCodecFactory.FILTER_NAME,
   113→                        new ProtocolCodecFilter(new FIXProtocolCodecFactory()));
   114→
   115→                ioAcceptor.setFilterChainBuilder(ioFilterChainBuilder);
   116→                ioAcceptor.setCloseOnDeactivation(false);
   117→                ioAcceptor.bind(socketDescriptor.getAddress());
   118→                log.info("Listening for connections at {} for session(s) {}", address, socketDescriptor.getAcceptedSessions().keySet());
   119→            } catch (IOException | GeneralSecurityException | ConfigError e) {
   120→                if (continueInitOnError) {
   121→                    log.warn("error during session initialization for session(s) {}, continuing...", socketDescriptor.getAcceptedSessions().keySet(), e);
   122→                } else {
   123→                    log.error("Cannot start acceptor session for {}, error: {}", address, e);
   124→                    throw new RuntimeError(e);
   125→                }
   126→            }
   127→        }
   128→    }
   129→
   130→    private void installSSL(AcceptorSocketDescriptor descriptor,
   131→            CompositeIoFilterChainBuilder ioFilterChainBuilder) throws GeneralSecurityException {
   132→        log.info("Installing SSL filter for {}", descriptor.getAddress());
   133→        SSLConfig sslConfig = descriptor.getSslConfig();
   134→        SSLContext sslContext = SSLContextFactory.getInstance(sslConfig);
   135→        SSLFilter sslFilter = new SSLFilter(sslContext);
   136→        sslFilter.setUseClientMode(false);
   137→        sslFilter.setNeedClientAuth(sslConfig.isNeedClientAuth());
   138→        sslFilter.setCipherSuites(sslConfig.getEnabledCipherSuites() != null ? sslConfig.getEnabledCipherSuites()
   139→                : SSLSupport.getDefaultCipherSuites(sslContext));
   140→        sslFilter.setEnabledProtocols(sslConfig.getEnabledProtocols() != null ? sslConfig.getEnabledProtocols()
   141→                : SSLSupport.getSupportedProtocols(sslContext));
   142→        ioFilterChainBuilder.addLast(SSLSupport.FILTER_NAME, sslFilter);
   143→    }
   144→
   145→    private IoAcceptor getIoAcceptor(AcceptorSocketDescriptor socketDescriptor) throws ConfigError {
   146→        int transportType = ProtocolFactory.getAddressTransportType(socketDescriptor.getAddress());
   147→        AcceptorSessionProvider sessionProvider = sessionProviders.
   148→                computeIfAbsent(socketDescriptor.getAddress(),
   149→                        k -> new DefaultAcceptorSessionProvider(socketDescriptor.getAcceptedSessions()));
   150→
   151→        IoAcceptor ioAcceptor = ioAcceptors.get(socketDescriptor);
   152→        if (ioAcceptor == null) {
   153→            ioAcceptor = ProtocolFactory.createIoAcceptor(transportType);
   154→            try {
   155→                SessionSettings settings = getSettings();
   156→                NetworkingOptions networkingOptions = new NetworkingOptions(settings.getDefaultProperties());
   157→                networkingOptions.apply(ioAcceptor);
   158→                ioAcceptor.setHandler(new AcceptorIoHandler(sessionProvider, settings, networkingOptions, getEventHandlingStrategy()));
   159→            } catch (FieldConvertError e) {
   160→                throw new ConfigError(e);
   161→            }
   162→            ioAcceptors.put(socketDescriptor, ioAcceptor);
   163→        }
   164→        return ioAcceptor;
   165→    }
   166→
   167→    private void setupSession(SessionSettings settings, SessionID sessionID, boolean isTemplate, Map<SessionID, Session> allSessions)
   168→            throws ConfigError, FieldConvertError {
   169→        int acceptTransportType = ProtocolFactory.SOCKET;
   170→        if (settings.isSetting(sessionID, Acceptor.SETTING_SOCKET_ACCEPT_PROTOCOL)) {
   171→            try {
   172→                acceptTransportType = ProtocolFactory.getTransportType(settings.getString(
   173→                        sessionID, Acceptor.SETTING_SOCKET_ACCEPT_PROTOCOL));
   174→            } catch (IllegalArgumentException e) {
   175→                // Unknown transport type
   176→                throw new ConfigError(e);
   177→            }
   178→        }
   179→
   180→        boolean useSSL = false;
   181→        SSLConfig sslConfig = null;
   182→        if (getSettings().isSetting(sessionID, SSLSupport.SETTING_USE_SSL)
   183→                && getSettings().getBool(sessionID, SSLSupport.SETTING_USE_SSL)) {
   184→            if (acceptTransportType == ProtocolFactory.SOCKET) {
   185→                useSSL = true;
   186→                sslConfig = SSLSupport.getSslConfig(getSettings(), sessionID);
   187→            } else {
   188→                log.warn("SSL will not be enabled for transport type={}, session={}", acceptTransportType, sessionID);
   189→            }
   190→        }
   191→
   192→        int acceptPort = (int) settings.getLong(sessionID, Acceptor.SETTING_SOCKET_ACCEPT_PORT);
   193→
   194→        String acceptHost = null;
   195→        if (settings.isSetting(sessionID, SETTING_SOCKET_ACCEPT_ADDRESS)) {
   196→            acceptHost = settings.getString(sessionID, SETTING_SOCKET_ACCEPT_ADDRESS);
   197→        }
   198→
   199→        SocketAddress acceptorAddress = ProtocolFactory.createSocketAddress(acceptTransportType,
   200→                acceptHost, acceptPort);
   201→
   202→        // Check for cached descriptor
   203→        AcceptorSocketDescriptor descriptor = socketDescriptorForAddress.get(acceptorAddress);
   204→        if (descriptor != null) {
   205→            if (descriptor.isUseSSL() != useSSL || !equals(sslConfig, descriptor.getSslConfig())) {
   206→                throw new ConfigError("Conflicting configurations of acceptor socket: " + acceptorAddress);
   207→            }
   208→        } else {
   209→            descriptor = new AcceptorSocketDescriptor(acceptorAddress, useSSL, sslConfig);
   210→            socketDescriptorForAddress.put(acceptorAddress, descriptor);
   211→        }
   212→
   213→        if (!isTemplate) {
   214→            Session session = sessionFactory.create(sessionID, settings);
   215→            descriptor.acceptSession(session);
   216→            allSessions.put(sessionID, session);
   217→        }
   218→    }
   219→
   220→    private boolean equals(Object object1, Object object2) {
   221→        return object1 == null ? object2 == null : object1.equals(object2);
   222→    }
   223→
   224→    private void createSessions(SessionSettings settings, boolean continueInitOnError) throws ConfigError {
   225→        Map<SessionID, Session> allSessions = new HashMap<>();
   226→        for (Iterator<SessionID> i = settings.sectionIterator(); i.hasNext();) {
   227→            SessionID sessionID = i.next();
   228→            try {
   229→                String connectionType = null;
   230→                if (settings.isSetting(sessionID, SessionFactory.SETTING_CONNECTION_TYPE)) {
   231→                    connectionType = settings.getString(sessionID,
   232→                            SessionFactory.SETTING_CONNECTION_TYPE);
   233→                }
   234→
   235→                if (SessionFactory.ACCEPTOR_CONNECTION_TYPE.equals(connectionType)) {
   236→                    boolean isTemplate = false;
   237→                    if (settings.isSetting(sessionID, Acceptor.SETTING_ACCEPTOR_TEMPLATE)) {
   238→                        try {
   239→                            isTemplate = settings.getBool(sessionID, Acceptor.SETTING_ACCEPTOR_TEMPLATE);
   240→                        } catch (FieldConvertError | ConfigError ex) {
   241→                            // ignore and use default
   242→                        }
   243→                    }
   244→
   245→                    setupSession(settings, sessionID, isTemplate, allSessions);
   246→                }
   247→            } catch (Throwable t) {
   248→                if (continueInitOnError) {
   249→                    log.warn("error during session initialization for {}, continuing...", sessionID, t);
   250→                } else {
   251→                    throw t instanceof ConfigError ? (ConfigError) t : new ConfigError(
   252→                            "error during session initialization", t);
   253→                }
   254→            }
   255→        }
   256→        setSessions(allSessions);
   257→
   258→        if (socketDescriptorForAddress.isEmpty()) {
   259→            throw new ConfigError("No acceptor sessions found in settings.");
   260→        }
   261→    }
   262→
   263→    protected void stopAcceptingConnections() {
   264→        Iterator<IoAcceptor> ioIt = getEndpoints().iterator();
   265→        while (ioIt.hasNext()) {
   266→            IoAcceptor ioAcceptor = ioIt.next();
   267→            SocketAddress localAddress = ioAcceptor.getLocalAddress();
   268→            ioAcceptor.unbind();
   269→            closeManagedSessionsAndDispose(ioAcceptor, true, log);
   270→            log.info("No longer accepting connections on {}", localAddress);
   271→            ioIt.remove();
   272→        }
   273→    }
   274→
   275→    private static class AcceptorSocketDescriptor {
   276→        private final SocketAddress address;
   277→        private final boolean useSSL;
   278→        private final SSLConfig sslConfig;
   279→        private final Map<SessionID, Session> acceptedSessions = new HashMap<>();
   280→
   281→        public AcceptorSocketDescriptor(SocketAddress address, boolean useSSL, SSLConfig sslConfig) {
   282→            this.address = address;
   283→            this.useSSL = useSSL;
   284→            this.sslConfig = sslConfig;
   285→        }
   286→
   287→        public void acceptSession(Session session) {
   288→            acceptedSessions.put(session.getSessionID(), session);
   289→        }
   290→
   291→        public Map<SessionID, Session> getAcceptedSessions() {
   292→            return Collections.unmodifiableMap(acceptedSessions);
   293→        }
   294→
   295→        public SocketAddress getAddress() {
   296→            return address;
   297→        }
   298→
   299→        public boolean isUseSSL() {
   300→            return useSSL;
   301→        }
   302→
   303→        public SSLConfig getSslConfig() {
   304→            return sslConfig;
   305→        }
   306→    }
   307→
   308→    public Collection<IoAcceptor> getEndpoints() {
   309→        return ioAcceptors.values();
   310→    }
   311→
   312→    public Map<SessionID, SocketAddress> getAcceptorAddresses() {
   313→        Map<SessionID, SocketAddress> sessionIdToAddressMap = new HashMap<>();
   314→        for (AcceptorSocketDescriptor descriptor : socketDescriptorForAddress.values()) {
   315→            for (SessionID sessionID : descriptor.getAcceptedSessions().keySet()) {
   316→                sessionIdToAddressMap.put(sessionID, descriptor.getAddress());
   317→            }
   318→        }
   319→        return sessionIdToAddressMap;
   320→    }
   321→
   322→    public void setSessionProvider(SocketAddress address, AcceptorSessionProvider provider) {
   323→        sessionProviders.put(address, provider);
   324→    }
   325→
   326→    static class StaticAcceptorSessionProvider implements AcceptorSessionProvider {
   327→        private final Map<SessionID, Session> acceptorSessions;
   328→
   329→        public StaticAcceptorSessionProvider(final Map<SessionID, Session> acceptorSessions) {
   330→            this.acceptorSessions = acceptorSessions;
   331→        }
   332→
   333→        public Session getSession(SessionID sessionID, SessionConnector connector) {
   334→            return acceptorSessions.get(sessionID);
   335→        }
   336→    }
   337→
   338→    public int getQueueSize() {
   339→        final EventHandlingStrategy ehs = getEventHandlingStrategy();
   340→        return ehs == null ? 0 : ehs.getQueueSize();
   341→    }
   342→
   343→    protected abstract EventHandlingStrategy getEventHandlingStrategy() ;
   344→
   345→    private class DefaultAcceptorSessionProvider implements AcceptorSessionProvider {
   346→
   347→        private final Map<SessionID, Session> acceptorSessions;
   348→
   349→        public DefaultAcceptorSessionProvider(Map<SessionID, Session> acceptorSessions) {
   350→            this.acceptorSessions = acceptorSessions;
   351→        }
   352→
   353→        public Session getSession(SessionID sessionID, SessionConnector ignored) {
   354→            Session session = acceptorSessions.get(sessionID);
   355→            if (session == null) {
   356→                SessionID reduced = reduceSessionID(sessionID);
   357→                session = acceptorSessions.get(reduced);
   358→            }
   359→            return session;
   360→        }
   361→
   362→        /**
   363→         * Remove the extra fields added to the session ID in QF-272.
   364→         */
   365→        private SessionID reduceSessionID(SessionID sessionID) {
   366→            // Acceptors don't use qualifiers.
   367→            return new SessionID(sessionID.getBeginString(), sessionID.getSenderCompID(),
   368→                    sessionID.getTargetCompID());
   369→        }
   370→    }
   371→
   372→}
